const b=$input.first().json.body||{};const H='https://old-hub.example/webhook/';const out=[];
for(const u of (b.urls||[])){try{const t0=Date.now();const r=await this.helpers.httpRequest({method:u.m||'GET',url:H+u.u,body:u.body,json:!u.raw,timeout:120000,returnFullResponse:!!u.raw,encoding:u.raw?'arraybuffer':undefined});
 if(u.raw){const buf=Buffer.from(r.body);const t=buf.toString('utf8');out.push({u:u.u,ms:Date.now()-t0,status:r.statusCode,ct:r.headers['content-type'],len:buf.length,find:(u.find||[]).map(f=>[f,t.indexOf(f)>-1])});}
 else{let v=r;if(u.pick)v=u.pick.reduce((m,k)=>{m[k]=r[k];return m;},{});if(u.days&&r.days)v.days=r.days.slice(0,u.days).map(d=>({day:d.day,activity:d.activity,planned:d.planned,weather:d.weather,entry:d.entry?{delay_cause:d.entry.delay_cause,delay_hours:d.entry.delay_hours,locked_at:d.entry.locked_at,history:d.entry.history}:null,people:d.auto&&d.auto.people}));out.push({u:u.u,ms:Date.now()-t0,body:v});}}catch(e){out.push({u:u.u,error:String(e.message).slice(0,300)});}}
return [{json:{out:out}}];
